// The ordered registry of topics (NeetCode's own order), as the site uses them.
// A problem is written as [name, difficulty, hint, learnTag?] in ./topics/*.js and gets its id from
// ./ids.js and its LeetCode details from ./leetcode.js (generated by scripts/leetcode-links.mjs).

import { RAW_TOPICS } from './topics.js';
import { problemId } from './ids.js';
import { LEETCODE, leetcodeUrl } from './leetcode.js';

export { problemId };

export const GROUPS = {
  found: 'Foundations',
  struct: 'Data structures',
  search: 'Search and graphs',
  dp: 'DP and greedy',
  misc: 'The rest',
};

export const TOPICS = RAW_TOPICS.map((t) => {
  const groups = t.groups.map((g) => ({
    ...g,
    items: g.items.map(([name, diff, hint, learn]) => {
      const id = problemId(t.id, name);
      const lc = LEETCODE[id];
      return {
        id, name, diff, hint, learn,
        topic: t.id,
        lc: lc ? { n: lc.n, slug: lc.slug, premium: lc.premium, url: leetcodeUrl(lc.slug) } : null,
      };
    }),
  }));
  return { ...t, groups, problems: groups.flatMap((g) => g.items) };
});

export const TOTAL = TOPICS.reduce((n, t) => n + t.problems.length, 0);

/** Every problem in NeetCode order, and lookups by id. */
export const PROBLEMS = TOPICS.flatMap((t) => t.problems);
export const PROBLEM_BY_ID = new Map(PROBLEMS.map((p) => [p.id, p]));
export const TOPIC_BY_ID = new Map(TOPICS.map((t) => [t.id, t]));

/** Problem counts by difficulty, e.g. { E: 28, M: 101, H: 21 }. */
export const DIFF_TOTALS = PROBLEMS.reduce((o, p) => ({ ...o, [p.diff]: (o[p.diff] ?? 0) + 1 }), { E: 0, M: 0, H: 0 });
